// Validate and normalise the incoming complaint BEFORE any model call.
// Both entry points converge here: the manual demo item, and the webhook body.
const TAXONOMY = {"Checking or savings account": ["Closing an account", "Managing an account", "Opening an account", "Problem caused by your funds being low", "Problem with a lender or other company charging your account", "OTHER"], "Credit card": ["Advertising and marketing, including promotional offers", "Closing your account", "Fees or interest", "Getting a credit card", "Incorrect information on your report", "Other features, terms, or problems", "Problem when making payments", "Problem with a company's investigation into an existing problem", "Problem with a purchase shown on your statement", "Struggling to pay your bill", "Trouble using your card", "OTHER"], "Money transfer, virtual currency, or money service": ["Confusing or missing disclosures", "Fraud or scam", "Managing, opening, or closing your mobile wallet account", "Money was not available when promised", "Other service problem", "Other transaction problem", "Problem with customer service", "Trouble accessing funds in your mobile or digital wallet", "Unauthorized transactions or other transaction problem", "Unexpected or other fees", "Wrong amount charged or received", "OTHER"], "Payday loan, title loan, personal loan, or advance loan": ["Can't contact lender or servicer", "Can't stop withdrawals from your bank account", "Charged fees or interest you didn't expect", "Getting a line of credit", "Getting the loan", "Incorrect information on your report", "Loan payment wasn't credited to your account", "Money was taken from your bank account on the wrong day or for the wrong amount", "Problem when making payments", "Problem with a company's investigation into an existing problem", "Problem with additional add-on products or services", "Problem with the payoff process at the end of the loan", "Received a loan you didn't apply for", "Struggling to pay your loan", "Vehicle was repossessed or sold the vehicle", "OTHER"], "Prepaid card": ["Advertising", "Problem getting a card or closing an account", "Problem with a purchase or transfer", "Trouble using the card", "Unexpected or other fees", "OTHER"], "Vehicle loan or lease": ["Getting a loan or lease", "Incorrect information on your report", "Managing the loan or lease", "Problem with a company's investigation into an existing problem", "Problems at the end of the loan or lease", "Repossession", "Struggling to pay your loan", "OTHER"]};
const MIN_CHARS = 20;
const MAX_CHARS = 6000;

const src = $input.first().json;
const raw = src.body ?? src;                       // webhook nests under .body

const clean = (v) => (typeof v === 'string' ? v.trim() : v);
const product   = clean(raw.product);
let   narrative = clean(raw.narrative);

const reject = (why) => {
  // Fail fast and loudly. No model call is made, so a malformed request costs nothing.
  throw new Error('REJECT_INVALID_INPUT: ' + why);
};

if (typeof product !== 'string' || !product)  reject('product is missing or not a string');
if (!(product in TAXONOMY))                   reject(`unknown product ${JSON.stringify(product)} - expected one of: ${Object.keys(TAXONOMY).join(', ')}`);
if (typeof narrative !== 'string' || !narrative) reject('narrative is missing or not a string');
if (narrative.length < MIN_CHARS)             reject(`narrative is ${narrative.length} characters; at least ${MIN_CHARS} are needed to classify`);

if (narrative.length > MAX_CHARS) narrative = narrative.slice(0, MAX_CHARS);

return [{ json: { product, narrative, narrative_chars: narrative.length } }];

// Parse the model's answer, then validate it before trusting it.
// Reason CODES and their order are generated from classifier/decide.py so the n8n POC and
// the LangSmith monitoring can never describe the same rejection differently.
const TAXONOMY = {"Checking or savings account": ["Closing an account", "Managing an account", "Opening an account", "Problem caused by your funds being low", "Problem with a lender or other company charging your account", "OTHER"], "Credit card": ["Advertising and marketing, including promotional offers", "Closing your account", "Fees or interest", "Getting a credit card", "Incorrect information on your report", "Other features, terms, or problems", "Problem when making payments", "Problem with a company's investigation into an existing problem", "Problem with a purchase shown on your statement", "Struggling to pay your bill", "Trouble using your card", "OTHER"], "Money transfer, virtual currency, or money service": ["Confusing or missing disclosures", "Fraud or scam", "Managing, opening, or closing your mobile wallet account", "Money was not available when promised", "Other service problem", "Other transaction problem", "Problem with customer service", "Trouble accessing funds in your mobile or digital wallet", "Unauthorized transactions or other transaction problem", "Unexpected or other fees", "Wrong amount charged or received", "OTHER"], "Payday loan, title loan, personal loan, or advance loan": ["Can't contact lender or servicer", "Can't stop withdrawals from your bank account", "Charged fees or interest you didn't expect", "Getting a line of credit", "Getting the loan", "Incorrect information on your report", "Loan payment wasn't credited to your account", "Money was taken from your bank account on the wrong day or for the wrong amount", "Problem when making payments", "Problem with a company's investigation into an existing problem", "Problem with additional add-on products or services", "Problem with the payoff process at the end of the loan", "Received a loan you didn't apply for", "Struggling to pay your loan", "Vehicle was repossessed or sold the vehicle", "OTHER"], "Prepaid card": ["Advertising", "Problem getting a card or closing an account", "Problem with a purchase or transfer", "Trouble using the card", "Unexpected or other fees", "OTHER"], "Vehicle loan or lease": ["Getting a loan or lease", "Incorrect information on your report", "Managing the loan or lease", "Problem with a company's investigation into an existing problem", "Problems at the end of the loan or lease", "Repossession", "Struggling to pay your loan", "OTHER"]};
const QUEUE_TO_TEAM = {"Closing an account": "Account servicing", "Closing your account": "Account servicing", "Managing an account": "Account servicing", "Managing, opening, or closing your mobile wallet account": "Account servicing", "Opening an account": "Account servicing", "Problem getting a card or closing an account": "Account servicing", "Trouble accessing funds in your mobile or digital wallet": "Account servicing", "Trouble using the card": "Account servicing", "Trouble using your card": "Account servicing", "Problem caused by your funds being low": "Account servicing", "Managing the loan or lease": "Account servicing", "Fraud or scam": "Disputes and fraud", "Money was not available when promised": "Disputes and fraud", "Other transaction problem": "Disputes and fraud", "Problem with a purchase or transfer": "Disputes and fraud", "Problem with a purchase shown on your statement": "Disputes and fraud", "Unauthorized transactions or other transaction problem": "Disputes and fraud", "Wrong amount charged or received": "Disputes and fraud", "Problem with a lender or other company charging your account": "Disputes and fraud", "Can't stop withdrawals from your bank account": "Disputes and fraud", "Money was taken from your bank account on the wrong day or for the wrong amount": "Disputes and fraud", "Charged fees or interest you didn't expect": "Payments and collections", "Fees or interest": "Payments and collections", "Loan payment wasn't credited to your account": "Payments and collections", "Problem when making payments": "Payments and collections", "Problem with the payoff process at the end of the loan": "Payments and collections", "Problems at the end of the loan or lease": "Payments and collections", "Struggling to pay your bill": "Payments and collections", "Struggling to pay your loan": "Payments and collections", "Unexpected or other fees": "Payments and collections", "Getting a credit card": "Originations", "Getting a line of credit": "Originations", "Getting a loan or lease": "Originations", "Getting the loan": "Originations", "Received a loan you didn't apply for": "Originations", "Problem with additional add-on products or services": "Originations", "Incorrect information on your report": "Credit reporting", "Problem with a company's investigation into an existing problem": "Credit reporting", "Repossession": "Asset recovery", "Vehicle was repossessed or sold the vehicle": "Asset recovery", "Advertising": "General enquiries", "Advertising and marketing, including promotional offers": "General enquiries", "Can't contact lender or servicer": "General enquiries", "Confusing or missing disclosures": "General enquiries", "Other features, terms, or problems": "General enquiries", "Other service problem": "General enquiries", "Problem with customer service": "General enquiries", "OTHER": "HUMAN_REVIEW"};
const THRESHOLD = 0.7;
const REASONS = {"OK_PROPOSED": "passed all checks", "REJECT_MALFORMED_OUTPUT": "model did not return valid JSON", "REJECT_QUEUE_NOT_IN_PRODUCT": "model proposed a queue that does not exist for this product", "REJECT_OUT_OF_TAXONOMY": "no queue on this product matches the complaint", "REJECT_LOW_CONFIDENCE": "confidence below the routing threshold", "REJECT_EVIDENCE_NOT_VERBATIM": "evidence quote is not verbatim from the complaint", "ERROR_MODEL_CALL": "the model call itself failed"};

const input = $('Normalise complaint').first().json;
const product = input.product;
const raw = $input.first().json.choices?.[0]?.message?.content ?? '{}';

let parsed = {}, malformed = false;
try { parsed = JSON.parse(raw); } catch (e) { malformed = true; }

const queue = String(parsed.queue ?? '');
const confidence = Number(parsed.confidence ?? 0);
const evidence = String(parsed.evidence ?? '');

const validQueues = TAXONOMY[product] ?? ['OTHER'];
const queueIsValid = validQueues.includes(queue);
// The quote must actually appear in the complaint. A fabricated quote manufactures false
// justification, which is worse than giving no justification at all.
const evidenceIsVerbatim = evidence.length > 0 &&
  input.narrative.toLowerCase().includes(evidence.slice(0, 60).toLowerCase());

// Guard order is declared, not emergent. A complaint failing two guards is always
// reported under the first, so the reason-code distribution stays comparable over time.
let code;
if (malformed)                   code = 'REJECT_MALFORMED_OUTPUT';
else if (!queueIsValid)          code = 'REJECT_QUEUE_NOT_IN_PRODUCT';
else if (queue === 'OTHER')      code = 'REJECT_OUT_OF_TAXONOMY';
else if (confidence < THRESHOLD) code = 'REJECT_LOW_CONFIDENCE';
else if (!evidenceIsVerbatim)    code = 'REJECT_EVIDENCE_NOT_VERBATIM';
else                             code = 'OK_PROPOSED';

const decision = code === 'OK_PROPOSED' ? 'PROPOSE_TO_HANDLER' : 'HUMAN_REVIEW';

return [{ json: {
  product,
  proposed_queue: queueIsValid ? queue : null,
  proposed_team: code === 'OK_PROPOSED' ? (QUEUE_TO_TEAM[queue] ?? 'HUMAN_REVIEW') : 'HUMAN_REVIEW',
  confidence,
  evidence,
  evidence_is_verbatim: evidenceIsVerbatim,
  decision,
  reason_code: code,
  reason: REASONS[code],
  narrative: input.narrative,
}}];

