  run_type: 'chain',
  start_time: new Date().toISOString(),
  end_time: new Date().toISOString(),
  session_name: "capstone-triage-live",
  inputs: { product: $json.product, narrative_chars: ($json.narrative || '').length },
  outputs: {
    decision: $json.decision, reason_code: $json.reason_code,
    proposed_team: $json.proposed_team, proposed_queue: $json.proposed_queue,
    confidence: $json.confidence, evidence_is_verbatim: $json.evidence_is_verbatim,
    environment: 'demo', source: 'n8n'
  }
}) }}
